const projects=[
{name:'SaudiLendGateAI',ar:'تحليل المستندات المالية',en:'Financial statement intelligence',category:'PROFESSIONAL / FINANCE',diagram:'PDF · XLSX · DOCX → RAG → JSON',tags:['FastAPI','Qdrant','Document AI','Azure'],desc:['An asynchronous RAG service that transforms financial documents into structured JSON across 14+ analysis types for lending and credit assessment.','خدمة RAG غير متزامنة تحوّل المستندات المالية إلى JSON منظم عبر أكثر من 14 نوعاً من التحليل لدعم الإقراض وتقييم الائتمان.'],detail:['Integrated Google Document AI OCR, OpenAI embeddings, and Qdrant retrieval. Background jobs and webhook callbacks support document processing; Docker and Azure DevOps CI/CD support delivery.','دمج Google Document AI OCR وتضمينات OpenAI والاسترجاع عبر Qdrant، مع مهام خلفية وإشعارات webhook ونشر Docker عبر Azure DevOps.']},
{name:'MCP-Borsa',en:'A coordinated brokerage assistant',ar:'مساعد وساطة متعدد الوكلاء',category:'PROFESSIONAL / AGENT SYSTEMS',diagram:'SUPERVISOR → RETRIEVAL + SQL → SSE',tags:['Dapr Agents','MCP','AKS','ArgoCD'],desc:['A supervisor that coordinates knowledge retrieval and read-only SQL agents, streaming responses directly to the frontend.','مشرف ينسّق بين وكلاء استرجاع المعرفة وSQL للقراءة فقط، مع بث الاستجابات مباشرة إلى الواجهة.'],detail:['Built a custom MCP client and guarded database access. Deployed the backend to Azure Kubernetes Service using ArgoCD GitOps.','تطوير عميل MCP مخصص وضوابط للوصول إلى قاعدة البيانات، ونشر الخلفية على Azure Kubernetes Service باستخدام ArgoCD GitOps.']},
{name:'Baseera',en:'Agentic company research',ar:'بحث ذكي عن الشركات',category:'PROFESSIONAL / RESEARCH',diagram:'COMPANY → SEARCH AGENTS → INSIGHTS',tags:['Nuxt','OpenAI Responses','Tavily','Cloudflare'],desc:['Company research with domain-restricted agentic web search, interchangeable providers, and concurrent browser-side batch processing.','بحث عن الشركات باستخدام وكلاء بحث ويب مقيدين بنطاقات محددة، ومزودي خدمة قابلين للتبديل ومعالجة دفعات متزامنة داخل المتصفح.'],detail:['Built on Cloudflare Workers with D1/R2 persistence and Langfuse tracing. Uses the OpenAI Responses API and Tavily for research.','تطبيق على Cloudflare Workers مع تخزين D1/R2 وتتبع Langfuse، باستخدام OpenAI Responses API وTavily للبحث.']},
{name:'SmartClaim / Hakeem AI',en:'Medical insurance claim validation',ar:'التحقق من مطالبات التأمين الطبي',category:'FREELANCE / HEALTHCARE',diagram:'PRESCRIPTION → VISION → VALIDATION',tags:['Gemini Vision','FastAPI','RabbitMQ','PostgreSQL'],desc:['From proof of concept to production: prescription extraction and claims validation against clinical and policy rules, with English and Arabic outputs.','من إثبات المفهوم إلى الإنتاج: استخراج بيانات الوصفات والتحقق من المطالبات وفق القواعد الطبية والتأمينية، بمخرجات عربية وإنجليزية.'],detail:['Delivered 13+ REST endpoints, JWT authentication, RBAC, multi-tenant accounts, and decision audit trails. Implemented idempotent retries, dead-letter queues, and 80+ unit and integration tests.','تنفيذ أكثر من 13 نقطة REST، ومصادقة JWT وصلاحيات RBAC وحسابات متعددة المستأجرين وسجلات تدقيق للقرارات، مع إعادة محاولات آمنة وطوابير للرسائل الفاشلة وأكثر من 80 اختباراً.']},
{name:'OrionIntel',en:'Modular RAG infrastructure',ar:'منصة RAG معيارية',category:'INDEPENDENT / OPEN SOURCE',diagram:'INGEST → CELERY → VECTOR RETRIEVAL',tags:['Celery','pgvector','Qdrant','Redis'],url:'https://github.com/0Xuser100/OrionIntel',desc:['Document ingestion and semantic retrieval with interchangeable pgvector and Qdrant backends, MongoDB persistence, and a containerized service stack.','إدخال المستندات والاسترجاع الدلالي عبر pgvector وQdrant القابلين للتبديل، مع تخزين MongoDB وحزمة خدمات داخل حاويات.'],detail:['Moved ingestion and indexing into Celery workflows, with task-status APIs, Redis-backed results, a PostgreSQL idempotency ledger, and scheduled cleanup.','نقل الإدخال والفهرسة إلى مهام Celery مع واجهات لحالة المهام ونتائج Redis وسجل PostgreSQL لمنع تكرار التنفيذ وتنظيف مجدول.']},
{name:'Temporal AI Agent',en:'Durable contract review',ar:'مراجعة العقود بسير عمل موثوق',category:'INDEPENDENT / WORKFLOW',diagram:'PDF → PARALLEL REVIEW → APPROVAL',tags:['Temporal','FastAPI','S3','LLMs'],url:'https://github.com/0Xuser100/Temporal-ai-agent',desc:['Parallel document reviews that combine LLM summaries into a risk report, with human approval and revision cycles.','مراجعات متوازية للمستندات تجمع ملخصات النماذج اللغوية في تقرير مخاطر، مع دورات موافقة ومراجعة بشرية.'],detail:['Uses Temporal Updates, Signals, and Queries, plus activity retries, timeouts, and heartbeats to coordinate the workflow.','استخدام Updates وSignals وQueries في Temporal، مع إعادة المحاولات والمهل الزمنية وheartbeats لتنسيق سير العمل.']},
{name:'Telegram Data Analyst',en:'From CSV to conversation',ar:'من ملفات CSV إلى التحليل',category:'INDEPENDENT / DATA AGENTS',diagram:'CSV → PYTHON → CHARTS + INSIGHTS',tags:['Deep Agents','LangGraph','Pandas','LangSmith'],url:'https://github.com/0Xuser100/telegram-data-analyst-agent',desc:['A Telegram and CLI agent that turns uploaded CSV files into Python analyses, charts, and summaries with configurable human approval.','وكيل عبر Telegram وسطر الأوامر يحوّل ملفات CSV إلى تحليلات Python ورسوم وملخصات، مع موافقات بشرية قابلة للضبط.'],detail:['Persistent conversations, resumable approvals, context compaction, and tracing. Includes 554 offline tests and architectural dependency checks.','محادثات مستمرة وموافقات قابلة للاستئناف وضغط للسياق وتتبع، مع 554 اختباراً دون اتصال وفحوص للتبعيات المعمارية.']},
{name:'Mechanism of Action',en:'Predicting drug mechanisms',ar:'التنبؤ بآليات عمل الأدوية',category:'GRADUATION / MACHINE LEARNING',diagram:'GENE EXPRESSION → ML → PREDICTION',tags:['TensorFlow','XGBoost','scikit-learn','Flask'],url:'https://github.com/0Xuser100/Mechanism-Of-Action-Graduation-Project-',desc:['Neural-network and autoencoder/XGBoost models for predicting drug mechanisms from gene-expression and cell-viability features.','نماذج شبكات عصبية وautoencoder/XGBoost للتنبؤ بآليات عمل الأدوية من التعبير الجيني وخصائص حيوية الخلايا.'],detail:['Trained on the Kaggle MoA dataset and served predictions through a Flask API and an interactive web interface.','التدريب على بيانات Kaggle MoA وتقديم التنبؤات عبر Flask API وواجهة ويب تفاعلية.']}
];
let lang='en';try{lang=localStorage.getItem('portfolio-lang')==='ar'?'ar':'en';document.documentElement.dataset.theme=localStorage.getItem('portfolio-theme')||'dark'}catch{}
const $=s=>document.querySelector(s), t=(en,ar)=>lang==='en'?en:ar;
const caseStudies = [
  {id:0, context:['ThinkTech / Financial AI','ThinkTech / الذكاء المالي'], problem:['Financial documents arrive in different formats and need structured analysis for lending and credit assessment.','المستندات المالية تصل بصيغ مختلفة وتحتاج إلى تحليل منظم لدعم الإقراض وتقييم الائتمان.'], role:['Built the asynchronous FastAPI RAG service, connecting OCR, embeddings, retrieval, background jobs, and webhook callbacks.','بناء خدمة RAG غير متزامنة باستخدام FastAPI، وربط OCR والتضمينات والاسترجاع والمهام الخلفية وإشعارات webhook.'], outcome:['Structured JSON across 14+ financial analysis types, with Docker delivery through Azure DevOps CI/CD.','مخرجات JSON منظمة عبر أكثر من 14 نوعاً من التحليل المالي، ونشر Docker عبر Azure DevOps CI/CD.'], metric:'14+', metricLabel:['financial analysis types','نوعاً من التحليل المالي'], steps:[['PDF / Excel / Word','PDF / Excel / Word'],['OCR + retrieval','OCR + استرجاع'],['Structured JSON','JSON منظم']], signal:['Asynchronous processing · Webhooks · CI/CD','معالجة غير متزامنة · Webhooks · CI/CD']},
  {id:3, context:['Freelance / Healthcare AI','عمل مستقل / التأمين الطبي'], problem:['Extract prescription data and validate insurance claims against clinical and policy rules, in English and Arabic.','استخراج بيانات الوصفات والتحقق من المطالبات التأمينية وفق القواعد الطبية والتأمينية، بالعربية والإنجليزية.'], role:['Led backend delivery from proof of concept to production: Gemini Vision extraction, RabbitMQ workers, and asynchronous PostgreSQL.','قيادة تطوير الخلفية من إثبات المفهوم إلى الإنتاج: استخراج عبر Gemini Vision وعمال RabbitMQ وPostgreSQL غير متزامن.'], outcome:['13+ REST endpoints with JWT, role-based access, multi-tenant accounts, decision audit trails, and 80+ tests.','أكثر من 13 نقطة REST مع JWT وصلاحيات حسب الدور وحسابات متعددة المستأجرين وسجلات تدقيق وأكثر من 80 اختباراً.'], metric:'80+',metricLabel:['unit & integration tests','اختبار وحدة وتكامل'], steps:[['Prescription','الوصفة الطبية'],['Vision + validation','الرؤية + التحقق'],['Auditable decision','قرار قابل للتدقيق']],signal:['13+ endpoints · Idempotent retries · Audit trails','أكثر من 13 نقطة API · إعادة محاولات آمنة · سجلات تدقيق']},
  {id:6, context:['Independent / Data agents','مشروع مستقل / وكلاء البيانات'], problem:['Turn CSV uploads into analyses, charts, and summaries, while keeping human approval over sensitive actions.','تحويل ملفات CSV إلى تحليلات ورسوم وملخصات، مع إبقاء الموافقة البشرية على الإجراءات الحساسة.'], role:['Built a Telegram and CLI agent with Deep Agents and LangGraph, persistent conversations, and resumable approvals.','بناء وكيل Telegram وسطر أوامر باستخدام Deep Agents وLangGraph، مع محادثات مستمرة وموافقات قابلة للاستئناف.'], outcome:['Python analyses and visualizations, backed by 554 offline tests including architectural dependency checks.','تحليلات Python ورسوم بيانية تدعمها 554 اختباراً دون اتصال، تشمل فحوص التبعيات المعمارية.'], metric:'554', metricLabel:['offline tests','اختباراً دون اتصال'],steps:[['CSV upload','رفع ملف CSV'],['Agent + Python','وكيل + Python'],['Charts + insights','رسوم + تحليلات']],signal:['Human approval · Persistent context · Tracing','موافقة بشرية · سياق مستمر · تتبع']}
];
let activeFilter = 'all';
const filterDefs = [ ['all','All projects','كل المشاريع'], ['agents','Agent systems','أنظمة الوكلاء'], ['rag','RAG & retrieval','RAG والاسترجاع'], ['ml','Machine learning','التعلم الآلي'] ];
function projectGroup(i){return i===7?'ml':i===4?'rag':'agents'}
function category(p){return p.category.split(' / ').map(x=>({PROFESSIONAL:'مهني',FINANCE:'التمويل','AGENT SYSTEMS':'أنظمة الوكلاء',RESEARCH:'البحث',FREELANCE:'عمل مستقل',HEALTHCARE:'التأمين الطبي',INDEPENDENT:'مشروع مستقل','OPEN SOURCE':'مفتوح المصدر',WORKFLOW:'سير العمل','DATA AGENTS':'وكلاء البيانات',GRADUATION:'مشروع التخرج','MACHINE LEARNING':'التعلم الآلي'}[x]||x)).join(' / ')}
function renderProjects(){
  const ix=lang==='en'?0:1;
  $('#featured').innerHTML=caseStudies.map((c,num)=>{const p=projects[c.id];return `<article class="case-study" id="case-${c.id}"><div class="case-art art-${num}"><div class="case-art-top"><span>0${num+1}</span><span>${c.context[ix]}</span></div><div class="case-metric"><strong>${c.metric}</strong><span>${c.metricLabel[ix]}</span></div><div class="case-flow">${c.steps.map((x,i)=>`<span><small>0${i+1}</small>${x[ix]}</span>`).join('<i aria-hidden="true">↓</i>')}</div><div class="case-signal">${c.signal[ix]}</div></div><div class="case-copy"><div class="eyebrow">${t('SELECTED PROJECT','مشروع بارز')} / 0${num+1}</div><h3>${p.name}</h3><p class="case-subtitle">${p[lang]}</p><dl><div><dt>${t('The challenge','التحدي')}</dt><dd>${c.problem[ix]}</dd></div><div><dt>${t('My contribution','مساهمتي')}</dt><dd>${c.role[ix]}</dd></div><div><dt>${t('Delivered','ما تم تنفيذه')}</dt><dd>${c.outcome[ix]}</dd></div></dl><div class="tags">${p.tags.map(x=>`<span class="tag">${x}</span>`).join('')}</div><div class="case-links"><details><summary>${t('Read engineering details','اقرأ التفاصيل الهندسية')} <span aria-hidden="true">+</span></summary><p>${p.detail[ix]}</p></details>${p.url?`<a class="text-link" href="${p.url}" target="_blank" rel="noopener">GitHub ↗</a>`:`<span class="work-context">${t('Professional project · CV summary','مشروع مهني · ملخص من السيرة الذاتية')}</span>`}</div></div></article>`}).join('');
  $('#project-filters').innerHTML=filterDefs.map(([key,en,ar])=>`<button type="button" data-filter="${key}" aria-pressed="${activeFilter===key}">${t(en,ar)}</button>`).join('');
  renderLibrary();
}
function renderLibrary(){
  const ix=lang==='en'?0:1;
  const ids=[1,2,4,5,7].filter(i=>activeFilter==='all'||projectGroup(i)===activeFilter);
  $('#projects').innerHTML=ids.map(i=>{const p=projects[i];return `<article class="project project-row" id="project-${i}"><div class="project-index" aria-hidden="true">${i===7?'ML':i===4?'RAG':'AI'}</div><div class="project-body"><div class="project-category">${lang==='en'?p.category:category(p)}</div><h3>${p.name}</h3><p class="project-subtitle">${p[lang]}</p><p>${p.desc[ix]}</p><div class="tags">${p.tags.map(x=>`<span class="tag">${x}</span>`).join('')}</div><details><summary>${t('Engineering details','تفاصيل هندسية')}</summary><p>${p.detail[ix]}</p></details></div><div class="project-action">${p.url?`<a href="${p.url}" target="_blank" rel="noopener" aria-label="${t('View source for','عرض مصدر')} ${p.name}">GitHub ↗</a>`:`<span>${t('Professional work','مشروع مهني')}</span>`}</div></article>`}).join('');
  $('#project-count').textContent=t(`Showing ${ids.length} of 5 additional projects`,`عرض ${ids.length} من 5 مشاريع إضافية`);
}
function render(){
  document.documentElement.lang=lang;
  document.documentElement.dir=lang==='ar'?'rtl':'ltr';
  document.title=t('Mahmoud Abdelhamid | AI Engineer · RAG & Agents','محمود عبد الحميد | مهندس ذكاء اصطناعي');
  document.querySelectorAll('[data-en]').forEach(e=>e.innerHTML=e.dataset[lang]);
  $('#language').textContent=lang==='en'?'AR / العربية':'EN / English';
  $('#language').setAttribute('aria-label',t('Switch to Arabic','التبديل إلى الإنجليزية'));
  $('#theme').textContent=document.documentElement.dataset.theme==='dark'?'☀':'☾';
  $('#theme').setAttribute('aria-label',t('Switch between light and dark mode','التبديل بين الوضع الفاتح والداكن'));
  $('#question').placeholder=t('Ask about projects, skills, or experience…','اسأل عن المشاريع أو المهارات أو الخبرة…');
  $('#chat-close').setAttribute('aria-label',t('Close chat','إغلاق المحادثة'));
  $('#chat-send').setAttribute('aria-label',t('Send question','إرسال السؤال'));
  $('#chat').setAttribute('aria-label',t('CV guide','دليل السيرة الذاتية'));
  $('#project-filters').setAttribute('aria-label',t('Filter projects','تصفية المشاريع'));
  renderProjects();
  $('#suggestions').innerHTML=[t('AI projects','مشاريع الذكاء الاصطناعي'),t('Work experience','الخبرات المهنية'),t('Technical skills','المهارات التقنية'),t('Education','التعليم')].map(x=>`<button type="button">${x}</button>`).join('');
  $('#messages').replaceChildren();
  message(t('Hi! I can guide you through Mahmoud’s projects, work experience, skills, and education. My answers are prepared from his CV. Choose a topic below or ask about a project by name.','مرحباً! أساعدك في استكشاف مشاريع محمود وخبراته ومهاراته وتعليمه. إجاباتي معدّة من سيرته الذاتية. اختر موضوعاً بالأسفل أو اسأل باسم مشروع.'));
}

function message(text,user=false,source=''){const e=document.createElement('div');e.className='message'+(user?' user':'');e.textContent=text;if(source){const s=document.createElement('small');s.textContent=t('Source: CV · ','المصدر: السيرة الذاتية · ')+source;e.appendChild(s)}$('#messages').appendChild(e);$('#messages').scrollTop=$('#messages').scrollHeight}
function answer(q){const n=q.toLowerCase();const index=lang==='en'?0:1;
const match=projects.find(p=>[p.name.toLowerCase(),...(p.name==='SaudiLendGateAI'?['saudilend','lending','financial','مالي','ائتمان']:[]),...(p.name==='MCP-Borsa'?['borsa','brokerage','بورصة','وساطة']:[]),...(p.name==='Baseera'?['بصيرة','company research','بحث الشركات']:[]),...(p.name.startsWith('SmartClaim')?['smartclaim','hakeem','insurance','medical','تأمين','طبي','حكيم']:[]),...(p.name==='OrionIntel'?['orion','اوريون']:[]),...(p.name==='Temporal AI Agent'?['temporal','contract','عقود']:[]),...(p.name==='Telegram Data Analyst'?['telegram','csv','تليجرام']:[]),...(p.name==='Mechanism of Action'?['drug','moa','graduation','أدوية','تخرج']:[])].some(k=>n.includes(k)));
if(match)return [match.name+' — '+match.desc[index]+'\n\n'+match.detail[index]+'\n\n'+match.tags.join(' · '),t('Selected projects / Professional experience','المشاريع المختارة / الخبرة المهنية')];
if(/contact|email|hire|reach|تواصل|بريد|اتصال|توظيف/.test(n))return [t('You can reach Mahmoud at mahmoudabdulhamid22@gmail.com. His GitHub is github.com/0Xuser100. Use the contact section for his LinkedIn profile and CV.','يمكنك التواصل مع محمود عبر mahmoudabdulhamid22@gmail.com. حسابه على GitHub هو github.com/0Xuser100. ستجد LinkedIn وسيرته الذاتية في قسم التواصل.'),t('Contact details','بيانات التواصل')];
if(/educat|university|gpa|degree|college|تعليم|جامع|معدل|دراس|بكالوريوس/.test(n))return [t('Mahmoud earned a B.S. in Computer Science at Menoufia University, Egypt (May 2020–May 2024). GPA: 3.65/4.0, Excellent with Honors, ranked 7th in the college. He competed in ECPC from 2020 to 2024 and coached in 2024.','حصل محمود على بكالوريوس علوم الحاسب من جامعة المنوفية بمصر (مايو 2020–مايو 2024)، بمعدل 3.65 من 4، وامتياز مع مرتبة الشرف، والمركز السابع على الكلية. شارك في ECPC من 2020 إلى 2024 وكان مدرباً في 2024.'),t('Education & Leadership','التعليم والأنشطة القيادية')];
if(/experience|work|thinktech|career|freelanc|خبر|عمل|وظيف|مسير/.test(n))return [t('Mahmoud is an AI Engineer at ThinkTech (June 2025–present), working on financial RAG, multi-agent brokerage assistance, and company research. He has also worked as a freelance AI & ML Engineer for independent clients / Upwork since July 2022. His freelance work includes leading SmartClaim from proof of concept to production.','يعمل محمود مهندس ذكاء اصطناعي في ThinkTech منذ يونيو 2025، في RAG المالي ومساعد الوساطة متعدد الوكلاء والبحث عن الشركات. ويعمل أيضاً مهندس ذكاء اصطناعي وتعلم آلي مستقلاً لعملاء مستقلين وعبر Upwork منذ يوليو 2022، بما يشمل قيادة SmartClaim من إثبات المفهوم إلى الإنتاج.'),t('Professional experience','الخبرة المهنية')];
if(/skill|stack|tool|python|framework|تقني|مهار|أدوات|بايثون/.test(n))return [t('His stack includes Python, SQL, TypeScript, FastAPI, LangChain, LangGraph, Deep Agents, Dapr Agents, MCP, RAG, OpenAI APIs and Gemini. Data and retrieval: PostgreSQL, pgvector, Qdrant and Redis. Delivery: Docker, Kubernetes, Azure, Cloudflare Workers and ArgoCD. ML: PyTorch, TensorFlow, scikit-learn and XGBoost.','تشمل مهاراته Python وSQL وTypeScript وFastAPI وLangChain وLangGraph وDeep Agents وDapr Agents وMCP وRAG وOpenAI APIs وGemini. للبيانات والاسترجاع: PostgreSQL وpgvector وQdrant وRedis. للنشر: Docker وKubernetes وAzure وCloudflare Workers وArgoCD. وللتعلم الآلي: PyTorch وTensorFlow وscikit-learn وXGBoost.'),t('Technical skills','المهارات التقنية')];
if(/project|ai|rag|llm|agent|مشروع|مشاريع|ذكاء|وكيل|وكلاء/.test(n))return [t('Mahmoud builds LLM applications, RAG systems and multi-agent workflows. His work includes:\n• SaudiLendGateAI — financial document analysis\n• MCP-Borsa — multi-agent brokerage assistant\n• Baseera — company research\n• SmartClaim / Hakeem AI — medical insurance validation\n• OrionIntel — modular RAG\n• Temporal AI Agent — contract review\n• Telegram Data Analyst — CSV analysis\nAsk about any project by name for details.','يطوّر محمود تطبيقات النماذج اللغوية وأنظمة RAG وسير العمل متعدد الوكلاء. تشمل أعماله:\n• SaudiLendGateAI — تحليل المستندات المالية\n• MCP-Borsa — مساعد وساطة متعدد الوكلاء\n• Baseera — البحث عن الشركات\n• SmartClaim / Hakeem AI — التحقق من التأمين الطبي\n• OrionIntel — منصة RAG معيارية\n• Temporal AI Agent — مراجعة العقود\n• Telegram Data Analyst — تحليل CSV\nاسأل باسم أي مشروع للمزيد.'),t('Professional experience & Selected projects','الخبرة المهنية والمشاريع المختارة')];
if(/test|quality|اختبار|جودة/.test(n))return [t('SmartClaim includes 80+ unit and integration tests. Telegram Data Analyst includes 554 offline tests, including architectural dependency checks. His CV also lists pytest, Langfuse and LangSmith.','يشمل SmartClaim أكثر من 80 اختبار وحدة وتكامل. ويشمل Telegram Data Analyst عدد 554 اختباراً دون اتصال، بما فيها فحوص التبعيات المعمارية. وتذكر سيرته pytest وLangfuse وLangSmith.'),t('Project delivery & Quality','تنفيذ المشاريع والجودة')];
if(/hello|hi\b|مرحبا|أهلا|who|about|من هو|نبذ/.test(n))return [t('Mahmoud Abdelhamid is an AI Engineer focused on LLM applications, retrieval-augmented generation (RAG), and multi-agent workflows. He combines machine learning with asynchronous backend engineering, testing, and cloud delivery. Ask about his projects, experience, skills, or education.','محمود عبد الحميد مهندس ذكاء اصطناعي يركز على تطبيقات النماذج اللغوية وRAG وسير العمل متعدد الوكلاء، ويجمع التعلم الآلي مع تطوير الخلفية غير المتزامنة والاختبارات والنشر السحابي. اسأل عن مشاريعه أو خبراته أو مهاراته أو تعليمه.'),t('Professional summary','الملخص المهني')];
return [t('I don’t have that information in Mahmoud’s CV. I’m a CV-based assistant with prepared answers, so try a project name, “work experience”, “technical skills”, or “education”. For other questions, contact Mahmoud by email.','لا أجد هذه المعلومة في سيرة محمود. أنا مساعد بإجابات معدّة من السيرة الذاتية؛ جرّب اسم مشروع أو «الخبرات المهنية» أو «المهارات التقنية» أو «التعليم». للأسئلة الأخرى، تواصل مع محمود عبر البريد.'),''];}
function ask(q){message(q,true);const [a,s]=answer(q);message(a,false,s)}
$('#project-filters').onclick=e=>{const b=e.target.closest('[data-filter]');if(!b)return;activeFilter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));renderLibrary()};
$('#year').textContent=new Date().getFullYear();$('#theme').onclick=()=>{const v=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=v;$('#theme').textContent=v==='dark'?'☀':'☾';try{localStorage.setItem('portfolio-theme',v)}catch{}};$('#language').onclick=()=>{lang=lang==='en'?'ar':'en';try{localStorage.setItem('portfolio-lang',lang)}catch{}render()};function chat(open){$('#chat').hidden=!open;$('#chat-launch').setAttribute('aria-expanded',String(open));if(open)$('#question').focus();else $('#chat-launch').focus()}$('#chat-launch').onclick=()=>chat($('#chat').hidden);$('#chat-close').onclick=()=>chat(false);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#chat').hidden)chat(false)});$('#chat-form').onsubmit=e=>{e.preventDefault();const q=$('#question').value.trim();if(q){ask(q);$('#question').value=''}};$('#suggestions').onclick=e=>{if(e.target.tagName==='BUTTON')ask(e.target.textContent)};render();
